const PixelFontBase64Data = "";
const DurinImageBase64Data = "";

window.htmlHeadContent = `
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<meta lang="zh-CN" />
<style>
  @font-face {
    font-family: "Pixel";
    src: url("data:font/truetype;charset=utf-8;base64,${PixelFontBase64Data}") format("truetype");
    font-weight: normal;
    font-style: normal;
    font-display: swap;
  }
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: "Pixel";
    user-select: none;
  }
  
  body {
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 20px;
    overflow-x: hidden;
    flex-direction: column;
    gap: 20px;

    background-image: url("data:image/png;base64,${DurinImageBase64Data}");
  
    /* 填充模式（全屏覆盖、不变形） */
    background-size: cover;     /* 关键：全屏填充 */
    background-position: center;/* 居中 */
    background-repeat: no-repeat;/* 不重复 */
    background-attachment: fixed;/* 固定背景（滚动页面不动） */
    background-color: #000;     /* 兜底黑色 */
  }
  
  /* 呼吸光效 */
  @keyframes pixelGlow {
    0%   { box-shadow: 0 0 18px #00ffff, 0 0 36px #ff1493, inset 0 0 12px #000; }
    50%  { box-shadow: 0 0 28px #00ffff, 0 0 56px #ff1493, inset 0 0 12px #000; }
    100% { box-shadow: 0 0 18px #00ffff, 0 0 36px #ff1493, inset 0 0 12px #000; }
  }
  
  /* 闪烁动画 */
  @keyframes pixelBlink {
    0%,100% { opacity:1; }
    50% { opacity:0.8; }
  }
  
  .control-panel {
    width: 100%;
    max-width: 1540px;
    background: rgba(10, 12, 34, 0.8);
    border: 4px solid #00ffff;
    padding: 30px;
    position: relative;
    animation: pixelGlow 4s ease infinite;
    image-rendering: pixelated;
  }
  
  .panel-title {
    text-align: center;
    margin-bottom: 25px;
    border-bottom: 3px solid #ff1493;
    padding-bottom:15px;
  }
  
  .panel-title h1 {
    color: #fff;
    font-size: 22px;
    text-shadow: 3px 0 0 #00ffff, 0 3px 0 #ff1493;
    letter-spacing: 2px;
    image-rendering: pixelated;
  }
  
  .panel-title p {
    color: #ccc;
    font-size: 10px;
    margin-top: 8px;
    text-shadow: 0 0 4px #00ffff;
    animation: pixelBlink 2s infinite;
  }
  
  .main {
    display: flex;
    flex-direction: column;
    row-gap: 25px;
  }
  
  .control-group {
    margin-top: 20px;
  }
  
  /* 标签 */
  .control-label {
    color: #00ffff;
    font-size: 12px;
    margin-bottom: 10px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    text-shadow: 1px 1px 0 #ff1493;
    letter-spacing:1px;
  }
  
  .value-display {
    color: #ff1493;
    text-shadow: 1px 1px 0 #00ffff;
  }
  
  /* 滑块 */
  input[type="range"] {
    -webkit-appearance: none;
    width: 100%;
    height: 10px;
    background: #111;
    border: 2px solid #00ffff;
    outline: none;
    border-radius:0;
  }
  
  input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    background: #ff1493;
    border:2px solid #fff;
    cursor: pointer;
    box-shadow: 0 0 8px #ff1493, 0 0 16px #00ffff;
    border-radius:0;
  }
  
  /* 取色器 */
  #colorPicker {
    width: 100%;
    height: 50px;
    border: 4px solid #00ffff;
    background: #111;
    cursor: pointer;
    border-radius:0;
    box-shadow: 0 0 8px #00ffff;
  }

  .palette-list {
    display: grid;
    height: 184px;
    gap: 8px;
    align-content: start;
    overflow-y: scroll;
    padding: 8px 6px 8px 8px;
    border: 2px solid #00ffff;
    border-radius: 8px;
    scrollbar-color: #00ffff transparent;
  }

  .palette-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
    align-items: center;
  }

  .palette-row.removable {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .palette-color {
    display: block;
    min-width: 0;
    width: 100%;
    height: 42px;
    padding: 3px;
    background: #111;
    border: 3px solid #00ffff;
    cursor: pointer;
  }

  .palette-remove, .palette-add {
    border: 2px solid #00ffff;
    color: #fff;
    background: #111;
    cursor: pointer;
    font-size: 11px;
  }

  .palette-remove {
    width: 34px;
    height: 34px;
    transition: background 0.1s, border-color 0.1s, color 0.1s, transform 0.1s;
  }

  .palette-add {
    width: 100%;
    margin-top: 8px;
    padding: 8px;
    transition: background 0.1s, border-color 0.1s, color 0.1s, transform 0.1s;
  }

  /* 按钮网格 */
  .mode-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6px;
  }

  .source-switch {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6px;
  }
  
  /* 按钮通用 */
  .pixel-btn {
    border: 3px solid;
    border-radius:0;
    font-weight:bold;
    cursor:pointer;
    transition:0.1s;
    image-rendering: pixelated;
  }
  
  .mode-btn {
    padding: 10px 4px;
    background: #111;
    border-color: #00ffff;
    color: #fff;
    font-size:11px;
    box-shadow: 2px 2px 0 #000;
  }
  
  .mode-btn:hover, .mode-btn.active {
    background: #ff1493;
    border-color: #ff1493;
    color: #000;
    transform: translate(-1px,-1px);
    box-shadow: 3px 3px 0 #000;
  }

  .source-button {
    padding: 10px 4px;
    background: #111;
    border-color: #00ffff;
    color: #fff;
    font-size: 11px;
  }

  .source-button:hover, .source-button.active, .palette-remove:hover, .palette-remove:active, .palette-add:hover, .palette-add:active {
    background: #ff1493;
    border-color: #ff1493;
    color: #000;
    transform: translate(-1px,-1px);
    box-shadow: 3px 3px 0 #000;
  }

  
  /* 电源按钮 */
  .power-switch {
    width: 100%;
    padding: 14px;
    font-size: 16px;
    background: #ff1493;
    color: #000;
    border: 4px solid #fff;
    box-shadow: 4px 4px 0 #000;
    transition: 0.1s;
    margin-top: 10px;
  }
  
  .power-switch:active {
    transform: translate(2px,2px);
    box-shadow: 2px 2px 0 #000;
  }
  
  .power-switch.off {
    background: #333;
    color: #666;
    border-color: #666;
    box-shadow: 4px 4px 0 #000;
  }
  
  .status-bar {
    text-align: center;
    margin-top: 20px;
    padding-top:15px;
    border-top:3px solid #00ffff;
    color: #ccc;
    font-size: 10px;
    text-shadow: 0 0 4px #00ffff;
    animation: pixelBlink 2.5s infinite;
  }
  
  /* 矩阵容器 */
  .matrix-container {
    display: flex;
    flex-direction: column;
    row-gap: 2px;
    justify-content: center;
    align-items: center;
    overflow-x: auto;
    width: 100%;
    padding: 12px;
    background: #000;
    border: 4px solid #00ffff;
    box-shadow: 0 0 12px #00ffff;
  }
  
  .pixel-row {
    display: flex;
    flex-direction: row;
    column-gap: 2px;
  }
  
  .pixel {
    width: 8px;
    height: 8px;
    background: #111;
    border: 1px solid #222;
    cursor: pointer;
    transition: 0.05s;
    image-rendering: pixelated;
  }
  
  .pixel:hover {
    transform: scale(1.15);
    border-color: #fff;
    box-shadow: 0 0 4px #fff;
  }
  
  /* 矩阵工具栏 */
  .matrix-toolbar {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 10px;
  }

  .matrix-paint-picker {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: 34px;
    margin-left: auto;
    padding: 4px 8px 4px 10px;
    color: #ccc;
    background: #111;
    border: 2px solid #00ffff;
    font-size: 10px;
    white-space: nowrap;
  }

  #paintColorPicker {
    width: 28px;
    height: 24px;
    padding: 1px;
    background: #000;
    border: 1px solid #fff;
    cursor: pointer;
  }
  
  .matrix-btn {
    padding: 8px 10px;
    background: #111;
    border: 3px solid #00ffff;
    color: #fff;
    font-size: 11px;
    box-shadow: 2px 2px 0 #000;
  }
  
  .matrix-btn:hover {
    background: #ff1493;
    border-color: #ff1493;
    color: #000;
    transform: translate(-1px,-1px);
    box-shadow: 3px 3px 0 #000;
  }
  
  /* 滚动条 */
  .matrix-container::-webkit-scrollbar {
    height: 8px;
  }
  .matrix-container::-webkit-scrollbar-thumb {
    background: #00ffff;
    border:2px solid #000;
  }
</style>`;

window.htmlBodyContent = `
<div class="control-panel">
  <div class="panel-title">
    <h1>AETHERIA DESKTOP/CLOUD LED</h1>
    <p>WS2812 CONTROL DESK</p>
  </div>
  <div class="main">
    <div class="matrix-section">
      <div class="control-label"> <span>144 × 6 LED MATRIX</span> </div>
      <div class="matrix-toolbar"> <button class="matrix-btn pixel-btn" id="clearMatrix">CLEAR</button> <button class="matrix-btn pixel-btn" id="invertMatrix">INVERT</button> <button class="matrix-btn pixel-btn" id="sendMatrix">SEND</button> <label class="matrix-paint-picker" title="仅改变矩阵画笔颜色"><span>BRUSH</span><input type="color" id="paintColorPicker" value="#00ffff" aria-label="矩阵画笔颜色"></label> </div>
      <div class="matrix-container" id="matrixContainer"></div>
    </div>
    <div class="left-controls">
      <div class="control-group">
        <div class="control-label"><span>OUTPUT SOURCE</span></div>
        <div class="source-switch" id="sourceSwitch"> <button class="source-button pixel-btn active" data-source="quick" type="button">快捷效果</button> <button class="source-button pixel-btn" data-source="matrix" type="button">自定义矩阵 </button> </div>
      </div>
      <div class="control-group">
        <div class="control-label"><span>QUICK COLORS</span><span>GRADIENT / SINGLE</span></div>
        <div class="palette-list" id="colorList">
          <div class="palette-row"><input type="color" class="palette-color" id="colorPicker" value="#ff0080" aria-label="默认快捷颜色"></div>
        </div>
        <button class="palette-add" id="addColor" type="button">+ ADD COLOR</button>
      </div>
      <div class="control-group">
        <div class="control-label"> <span>BRIGHTNESS</span> <span id="brightValue" class="value-display">80%</span> </div> <input type="range" id="brightness" min="0" max="100" value="80">
      </div>
      <div class="control-group">
        <div class="control-label"> <span>SPEED</span> <span id="speedValue" class="value-display">50</span> </div> <input type="range" id="speed" min="10" max="200" value="50">
      </div>
      <div class="control-group">
        <div class="control-label"><span>LED MODE</span></div>
        <div class="mode-grid"> <button class="mode-btn pixel-btn active">静态常亮</button> <button class="mode-btn pixel-btn">呼吸渐变</button> <button class="mode-btn pixel-btn">流光溢彩</button> </div>
      </div>
    </div>
  </div>
  <div class="status-bar"> <span>STATUS: ONLINE | MATRIX: 144×6 | DEVICE: PIXEL_8BIT</span> </div>
</div>`;

window.DurinImageBase64Data = DurinImageBase64Data;
